<?php
namespace Tests\Feature;
use App\Models\{User,Apprentice,Programme,LearningTask};
use App\Support\{JourneyMarker as M,JourneyEvents};
use Illuminate\Foundation\Testing\LazilyRefreshDatabase;
use PHPUnit\Framework\Attributes\TestWith;
use Tests\TestCase;
class JourneyMarker55Test extends TestCase {
 use LazilyRefreshDatabase;
 private function f(?string$code='ST0068',bool$active=true):array{$this->travelTo(now()->setDate(2026,11,16)->setTime(12,0));$u=User::factory()->create(['role'=>'apprentice']);$p=$code?Programme::factory()->create(['standard_code'=>$code,'active'=>$active]):null;$a=Apprentice::factory()->create(['user_id'=>$u->id,'programme_id'=>$p?->id,'programme'=>'Heavy Vehicle legacy text','start_date'=>'2026-09-01']);return[$u,$a];}
 #[TestWith(['ST0068','lorry'])] #[TestWith(['ST0033','car'])] #[TestWith(['ST0499','car'])] #[TestWith(['ST0403','car'])] #[TestWith(['ST0448','car'])] #[TestWith(['ST0070','neutral'])] #[TestWith([null,'neutral'])]
 public function test_marker_automatically_uses_linked_active_programme_code(?string$code,string$type):void{[$u,$a]=$this->f($code);$v=M::for($a,JourneyEvents::for($a));$this->assertSame($type,$v['vehicle']);$this->actingAs($u)->get(route('journey.show',$a))->assertOk()->assertSee('journey-vehicle--'.$type,false)->assertSee('Latest recorded point')->assertSee('aria-current="step"',false);}
 public function test_inactive_programme_does_not_guess_vehicle_from_legacy_text():void{[$u,$a]=$this->f('ST0068',false);$this->assertSame('neutral',M::for($a,JourneyEvents::for($a))['vehicle']);}
 public function test_only_latest_real_non_future_date_advances_marker_and_ties_are_explicit():void{[$u,$a]=$this->f();$events=[['date'=>'2026-09-01'],['date'=>'2026-11-02'],['date'=>'2026-11-02'],['date'=>'2026-12-01'],['date'=>'2026-11-99'],['date'=>'not-a-date']];$v=M::for($a,$events);$this->assertSame(2,$v['index']);$this->assertSame(1,$v['previous_index']);$this->assertSame('2026-11-02',$v['date']);$this->assertSame(2,$v['same_date_records']);}
 public function test_no_recorded_date_means_no_vehicle_no_pulse_and_no_invented_progress():void{[$u,$a]=$this->f();$a->start_date=null;$a->save();$this->assertNull(M::for($a,[])['index']);$this->actingAs($u)->get(route('journey.show',$a))->assertOk()->assertSee('No dated milestones recorded yet')->assertDontSee('data-journey-vehicle',false)->assertDontSee('data-journey-motion aria-',false);}
 public function test_latest_approved_task_position_is_read_only_and_future_decisions_do_not_move_it():void{[$u,$a]=$this->f('ST0499');LearningTask::factory()->create(['apprentice_id'=>$a->id,'status'=>'Approved','title'=>'Latest recorded approval55','submissions'=>[['decision'=>['date'=>'2026-11-10','feedback'=>'Recorded feedback']]]]);LearningTask::factory()->create(['apprentice_id'=>$a->id,'status'=>'Approved','title'=>'FUTURE-TASK55','reference'=>'future55','submissions'=>[['decision'=>['date'=>'2026-12-10','feedback'=>'Future feedback']]]]);$before=LearningTask::count();$v=M::for($a,JourneyEvents::for($a));$this->assertSame('2026-11-10',$v['date']);$this->actingAs($u)->get(route('journey.show',$a))->assertOk()->assertSee('Latest recorded point · 10/11/2026')->assertSee('journey-car55.svg',false)->assertDontSee('FUTURE-TASK55');$this->assertSame($before,LearningTask::count());}
 public function test_other_apprentice_cannot_read_the_road_or_vehicle_details():void{[$u,$a]=$this->f();$other=User::factory()->create(['role'=>'apprentice']);$this->actingAs($other)->get(route('journey.show',$a))->assertForbidden();}
 public function test_vehicle_art_is_static_svg_without_external_resources_or_scripts():void{foreach(['car','lorry']as$type){$xml=file_get_contents(public_path('assets/journey-'.$type.'55.svg'));$this->assertStringContainsString('>GTA</text>',$xml);$this->assertStringNotContainsString('<script',$xml);$this->assertStringNotContainsString('href=',$xml);$this->assertStringNotContainsString('<animate',$xml);$this->assertNotFalse(simplexml_load_string($xml));}}
}
